.darma-loader-darma-b7-yin-yang-spin { --accent: var(--loader-color, #0f172a); --accent-2: var(--loader-secondary-color, #e2e8f0); width: var(--loader-size, 68px); height: var(--loader-size, 68px); border-radius: 50%; background: linear-gradient(to bottom, var(--accent-2) 50%, var(--accent) 50%); position: relative; animation: darma-loader-darma-b7-yin-yang-spin-taichi calc(var(--loader-speed, 1s) * 1.8) linear infinite; }
.darma-loader-darma-b7-yin-yang-spin::before, .darma-loader-darma-b7-yin-yang-spin::after { content: ''; position: absolute; left: 25%; width: 50%; height: 50%; border-radius: 50%; box-sizing: border-box; }
.darma-loader-darma-b7-yin-yang-spin::before { top: 0; background: var(--accent); }
.darma-loader-darma-b7-yin-yang-spin::after { top: 50%; background: var(--accent-2); }
@keyframes darma-loader-darma-b7-yin-yang-spin-taichi { to { transform: rotate(360deg); } }

